<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { generateTestData, getTestOrganizations, getTestVehicles } from '@/api/adminOperationsApi'
import type { AdminTestDataOrganization } from '@/models/AdminTestDataOrganization'
import type { AdminTestDataVehicle } from '@/models/AdminTestDataVehicle'
const organizations = ref<AdminTestDataOrganization[]>([]), vehicles = ref<AdminTestDataVehicle[]>([]), organizationId = ref(''), vehicleId = ref(''), search = ref(''), action = ref<'vehicles'|'maintenances'|'defects'|null>(null), count = ref(10), mode = ref('completed'), error = ref(''), success = ref(''), isSaving = ref(false)
onMounted(loadOrganizations)
async function loadOrganizations() { try { organizations.value = await getTestOrganizations(search.value) } catch { error.value = 'Не удалось загрузить организации.' } }
async function loadVehicles() { vehicleId.value = ''; vehicles.value = organizationId.value ? await getTestVehicles(organizationId.value) : [] }
function open(next: 'vehicles'|'maintenances'|'defects') { action.value = next; count.value = next === 'maintenances' ? 20 : 10 }
async function generate() { if (isSaving.value || !organizationId.value || (action.value !== 'vehicles' && !vehicleId.value)) return; const base = `/api/v1/admin/test-data/organizations/${organizationId.value}`; const path = action.value === 'vehicles' ? `${base}/vehicles/generate` : `${base}/vehicles/${vehicleId.value}/${action.value}/generate`; isSaving.value = true; try { const result = await generateTestData(path, count.value, action.value === 'maintenances' ? mode.value : undefined); success.value = result.message; action.value = null; await loadOrganizations(); await loadVehicles() } catch { error.value = 'Не удалось создать тестовые данные.' } finally { isSaving.value = false } }
</script>
<template><section class="operations-page operation-form-page"><h1>Тестовые данные</h1><div v-if="error" class="form-message form-message--error">{{ error }}</div><div v-if="success" class="form-message form-message--success">{{ success }}</div><div class="standalone-form"><div class="operations-toolbar"><input v-model="search" placeholder="Организация или владелец" @keyup.enter="loadOrganizations"><button class="secondary-button" @click="loadOrganizations">Найти</button></div><label><span>Организация</span><SearchSelect v-model="organizationId" :options="organizations.map(item => ({ value: item.id, label: `${item.name} · ${item.ownerEmail}` }))" placeholder="Выберите организацию" @change="loadVehicles" /></label><label><span>Техника</span><SearchSelect v-model="vehicleId" :disabled="!organizationId" :options="vehicles.map(item => ({ value: item.id, label: [item.displayName, item.name].filter(Boolean).join(' · ') }))" placeholder="Выберите технику" /></label><div class="modal-actions"><button class="primary-button" :disabled="!organizationId" @click="open('vehicles')">Создать технику</button><button class="secondary-button" :disabled="!vehicleId" @click="open('maintenances')">Создать обслуживания</button><button class="secondary-button" :disabled="!vehicleId" @click="open('defects')">Создать дефекты</button></div></div><div v-if="action" class="modal-backdrop" @click.self="action = null"><form class="modal-card modal-card--compact" @submit.prevent="generate"><div class="modal-heading"><strong>Создание тестовых данных</strong><button type="button" @click="action = null">×</button></div><label><span>Количество</span><input v-model.number="count" type="number" min="1" :max="action === 'maintenances' ? 300 : 100" required></label><label v-if="action === 'maintenances'"><span>Режим</span><SearchSelect v-model="mode" :options="[{ value: 'completed', label: 'Завершённые' }, { value: 'planned', label: 'Запланированные' }]" /></label><div class="modal-actions"><button class="primary-button" :disabled="isSaving">Создать</button><button class="secondary-button" type="button" @click="action = null">Отмена</button></div></form></div></section></template>
